function proveGrossRounding(ctx, doc, expected, actual) {
  const payload=ctx.documentPayload||{};
  const requested=payload.items;
  const received=doc.items;
  if(!['CREATE_PROFORMA','CREATE_INVOICE'].includes(ctx.job?.job_type) ||
     payload.calc_vat_from!==1 || Number(doc.calc_vat_from)!==1 ||
     String(doc.currency)!==String(payload.currency) ||
     String(doc.number)!==String(ctx.documentNumber) ||
     String(doc.external_id)!==String(ctx.job.idempotency_key) ||
     String(doc.type)!==String(payload.type) ||
     !Array.isArray(requested)||!requested.length||
     !Array.isArray(received)||received.length!==requested.length) return {};
  const rate=Number(requested[0].vat_percent);
  if(!Number.isFinite(rate)||rate<=0||rate>100) return {};
  let gross=0, lineRoundedNet=0;
  for(let index=0;index<requested.length;index++) {
    const want=requested[index], got=received[index];
    const quantity=Number(want.quantity), price=Number(want.single_price_gross);
    if(!Number.isFinite(quantity)||quantity<=0||!Number.isFinite(price)||price<0||
       Number(want.vat_percent)!==rate||Number(got.vat_percent)!==rate||
       Number(got.quantity)!==quantity||!Number.isFinite(Number(got.single_price_gross))||
       Math.abs(Number(got.single_price_gross)-price)>Number.EPSILON*Math.max(1,Math.abs(price))*4||
       String(got.description)!==String(want.description)||
       Number(got.discount||0)!==0) return {};
    const lineGross=Math.round(quantity*price);
    gross+=lineGross;
    lineRoundedNet+=Math.round(lineGross*100/(100+rate));
  }
  const aggregateNet=Math.round(gross*100/(100+rate));
  if(gross!==expected.grossCents||gross!==actual.grossCents||
     lineRoundedNet!==expected.netCents||
     expected.vatCents!==gross-lineRoundedNet||
     actual.netCents!==aggregateNet||actual.vatCents!==gross-aggregateNet) return {};
  return {method:'GROSS_AGGREGATE_VS_ROUNDED_LINES',vatPercent:rate,lineCount:requested.length,
    sourceAmounts:expected,documentAmounts:actual,netDifferenceCents:actual.netCents-expected.netCents};
}

const ctx=$('Prepare Easybill Command').first().json;
const doc=$json.body??$json;
if(!doc.id||doc.is_draft===true)throw new Error('easybill_document_not_finalized');
let actualGrossCents=Number(doc.amount);
let actualNetCents=Number(doc.amount_net);
if(!Number.isInteger(actualGrossCents)||!Number.isInteger(actualNetCents))throw new Error('FATAL_easybill_document_amounts_missing');
let actualVatCents=actualGrossCents-actualNetCents;
let expectedNetCents;
let expectedVatCents;
let expectedGrossCents;
const jobType=String(ctx.job?.job_type||'');
if(['CREATE_PROFORMA','CREATE_INVOICE','CREATE_CANCELLATION'].includes(jobType)){
  expectedNetCents=Number(ctx.billingCase?.subtotal_net_cents);
  expectedVatCents=Number(ctx.billingCase?.vat_cents);
  expectedGrossCents=Number(ctx.billingCase?.total_gross_cents);
}else if(jobType==='CREATE_CREDIT'){
  expectedNetCents=Number(ctx.job?.payload?.netCents);
  expectedVatCents=Number(ctx.job?.payload?.vatCents);
  expectedGrossCents=Number(ctx.job?.payload?.grossCents ?? ctx.job?.payload?.amountCents);
}
if(['CREATE_CREDIT','CREATE_CANCELLATION'].includes(jobType)){
  actualGrossCents=Math.abs(actualGrossCents);
  actualNetCents=Math.abs(actualNetCents);
  actualVatCents=Math.abs(actualVatCents);
  expectedGrossCents=Math.abs(expectedGrossCents);
  expectedNetCents=Math.abs(expectedNetCents);
  expectedVatCents=Math.abs(expectedVatCents);
}
if(!Number.isInteger(expectedNetCents)||!Number.isInteger(expectedVatCents)||!Number.isInteger(expectedGrossCents)){
  throw new Error('FATAL_billing_expected_document_amounts_missing');
}
if(expectedNetCents+expectedVatCents!==expectedGrossCents){
  throw new Error('FATAL_billing_expected_document_amounts_inconsistent');
}
const roundingAttempt=proveGrossRounding(ctx,doc,
  {netCents:expectedNetCents,vatCents:expectedVatCents,grossCents:expectedGrossCents},
  {netCents:actualNetCents,vatCents:actualVatCents,grossCents:actualGrossCents});
const roundingProof=roundingAttempt.method?roundingAttempt:null;
if((actualNetCents!==expectedNetCents||actualVatCents!==expectedVatCents||actualGrossCents!==expectedGrossCents)&&!roundingProof){
  throw new Error('FATAL_easybill_document_amount_mismatch:'+String(doc.number||ctx.documentNumber||'')+
    ':expected='+expectedNetCents+','+expectedVatCents+','+expectedGrossCents+
    ':actual='+actualNetCents+','+actualVatCents+','+actualGrossCents);
}
const result=Object.assign({},ctx,{
  easybillDocument:doc,
  emailWasAlreadySent:Boolean(doc.last_postbox_id),
  roundingProof,
  verifiedDocumentAmounts:{netCents:actualNetCents,vatCents:actualVatCents,grossCents:actualGrossCents}
});
return [{json:result}];

